from flask import Flask, request, jsonify

app = Flask(__name__)
comments = []

@app.route('/comment', methods=['POST'])
def add_comment():
    comment = request.form.get('comment', '')
    comments.append(comment)
    return jsonify(success=True)

@app.route('/comments')
def show_comments():
    html = '<html><body><h1>Comments</h1><ul>'
    for c in comments:
        html += f'<li>{c}</li>'
    html += '</ul></body></html>'
    return html

if __name__ == '__main__':
    app.run()

from flask import Flask, request, jsonify
from markupsafe import escape

app = Flask(__name__)
comments = []

@app.route('/comment', methods=['POST'])
def add_comment():
    comment = escape(request.form.get('comment', ''))
    comments.append(str(comment))
    return jsonify(success=True)

@app.route('/comments')
def show_comments():
    items = ''.join(f'<li>{c}</li>' for c in comments)
    return f'<html><body><h1>Comments</h1><ul>{items}</ul></body></html>'

if __name__ == '__main__':
    app.run()

